/**
 * The brand faces, subset to Latin and embedded as data URIs.
 *
 * These were previously fetched as remote assets at runtime, which meant a slow
 * link (or a cold tunnel) painted the app in fallback type before the fonts
 * arrived. Embedding removes that failure mode on web entirely; native still
 * loads the same faces through expo-font.
 *
 * Regenerate with pyftsubset if the type scale or character set changes.
 */
export const EMBEDDED_FONTS: Record<string, string> = {
  'Plus Jakarta Sans':
    '',
  'Plus Jakarta Sans Medium':
    '',
  'Plus Jakarta Sans SemiBold':
    '',
  'Plus Jakarta Sans Bold':
    '',
  'Plus Jakarta Sans ExtraBold':
    '',
  'Instrument Serif':
    '',
};
